188	export function runIsolatedProcess(spec, { outputLimit = 16_384, input = "" } = {}) {
189	  const child = spawn(spec.cmd, spec.argv, { cwd: "/", env: {}, detached: true, stdio: ["pipe", "pipe", "pipe"] });
190	  return new Promise((resolve) => {
191	    let stdout = "";
192	    let stderr = "";
193	    let bytes = 0;
194	    let timedOut = false;
195	    let overflow = false;
196	    let settled = false;
197	    const killGroup = (signal) => { try { process.kill(-child.pid, signal); } catch {} };
198	    const collect = (target, chunk) => {
199	      bytes += chunk.length;
200	      if (bytes > outputLimit) { overflow = true; killGroup("SIGKILL"); return; }
201	      if (target === "stdout") stdout += chunk.toString("utf8");
202	      else stderr += chunk.toString("utf8");
203	    };
204	    child.stdout.on("data", (chunk) => collect("stdout", chunk));
205	    child.stderr.on("data", (chunk) => collect("stderr", chunk));
206	    child.stdin.on("error", () => {}); // A timed-out or rejecting child may close stdin before the bounded input is sent.
207	    child.stdin.end(input);
208	    const timer = setTimeout(() => { timedOut = true; killGroup("SIGTERM"); setTimeout(() => killGroup("SIGKILL"), 250).unref(); }, spec.timeoutMs);
209	    child.on("error", (error) => {
210	      if (settled) return;
211	      settled = true;
212	      clearTimeout(timer);
213	      resolve({ status: null, stdout, stderr, error: error.message, timedOut, overflow });
214	    });
215	    child.on("close", (status, signal) => {
216	      if (settled) return;
217	      settled = true;
218	      clearTimeout(timer);
219	      killGroup("SIGKILL");
220	      resolve({ status, signal, stdout, stderr, timedOut, overflow });
221	    });
222	  });
223	}
