225	/** Grant only the dedicated evaluator uid access to disposable paths; never make them world-writable. */
226	export function grantRunAsAccess(user, targets) {
227	  if (!/^[a-z_][a-z0-9_-]{0,31}$/.test(user)) throw new Error("invalid evaluator account");
228	  const setfacl = "/usr/bin/setfacl";
229	  if (!fs.existsSync(setfacl)) throw new Error("setfacl is unavailable; refusing unsafe workspace permission changes");
230	  for (const target of targets) {
231	    const resolved = fs.realpathSync(target);
232	    const result = spawnSync(setfacl, ["-R", "-m", `u:${user}:rwX`, resolved], { encoding: "utf8", timeout: 5000, env: { PATH: "/usr/bin:/bin" } });
233	    if (result.status !== 0) throw new Error(`could not grant scoped evaluator access to disposable path (${result.status ?? "signal"})`);
234	    if (fs.statSync(resolved).isDirectory()) {
235	      const defaults = spawnSync(setfacl, ["-m", `d:u:${user}:rwx`, resolved], { encoding: "utf8", timeout: 5000, env: { PATH: "/usr/bin:/bin" } });
236	      if (defaults.status !== 0) throw new Error(`could not set scoped evaluator default ACL (${defaults.status ?? "signal"})`);
237	    }
238	  }
239	}
