241	/** Execute a task-controlled shell command in a no-network, clear-environment namespace. */
242	export function runIsolated(command, { cwd, home = false, timeoutSec = 300, outputLimit = 1_000_000 } = {}) {
243	  const spec = isolatedArgv({ cwd, home, command, timeoutSec });
244	  return new Promise((resolve) => {
245	    const child = spawn(spec.cmd, spec.argv, { cwd: "/", env: {}, detached: true, stdio: ["ignore", "pipe", "pipe"] });
246	    let stdout = "";
247	    let stderr = "";
248	    let bytes = 0;
249	    let timedOut = false;
250	    let overflow = false;
251	    let settled = false;
252	    const killTree = (signal) => {
253	      try { process.kill(-child.pid, signal); } catch {}
254	    };
255	    const append = (target, chunk) => {
256	      bytes += chunk.length;
257	      if (bytes > outputLimit) {
258	        overflow = true;
259	        killTree("SIGKILL");
260	        return;
261	      }
262	      if (target === "stdout") stdout += chunk.toString("utf8");
263	      else stderr += chunk.toString("utf8");
264	    };
265	    child.stdout.on("data", (chunk) => append("stdout", chunk));
266	    child.stderr.on("data", (chunk) => append("stderr", chunk));
267	    const timer = setTimeout(() => {
268	      timedOut = true;
269	      killTree("SIGTERM");
270	      setTimeout(() => killTree("SIGKILL"), 250).unref();
271	    }, spec.timeoutMs);
272	    child.on("error", (error) => {
273	      if (settled) return;
274	      settled = true;
275	      clearTimeout(timer);
276	      resolve({ status: null, stdout, stderr, error: error.message, timedOut, overflow });
277	    });
278	    child.on("close", (status, signal) => {
279	      if (settled) return;
280	      settled = true;
281	      clearTimeout(timer);
282	      killTree("SIGKILL");
283	      resolve({ status, signal, stdout, stderr, timedOut, overflow });
284	    });
285	  });
286	}
