288	/** Resolve task-controlled paths without permitting traversal or symlink redirection. */
289	export function confinedPath(root, relative, { allowMissingLeaf = false } = {}) {
290	  if (typeof relative !== "string" || !relative || path.isAbsolute(relative) || relative.includes("\0")) {
291	    throw new Error("task path must be a non-empty relative path");
292	  }
293	  const parts = relative.split(/[\\/]+/);
294	  if (parts.some((part) => !part || part === "." || part === "..")) throw new Error(`unsafe task path: ${relative}`);
295	  const base = fs.realpathSync(root);
296	  let current = base;
297	  for (let i = 0; i < parts.length; i++) {
298	    current = path.join(current, parts[i]);
299	    let stat;
300	    try { stat = fs.lstatSync(current); }
301	    catch (error) {
302	      if (allowMissingLeaf && i === parts.length - 1 && error.code === "ENOENT") return current;
303	      throw new Error(`task path does not exist: ${relative}`);
304	    }
305	    if (stat.isSymbolicLink()) throw new Error(`task path contains a symlink: ${relative}`);
306	    if (i < parts.length - 1 && !stat.isDirectory()) throw new Error(`task path parent is not a directory: ${relative}`);
307	  }
308	  const resolved = fs.realpathSync(current);
309	  if (resolved !== base && !resolved.startsWith(`${base}${path.sep}`)) throw new Error(`task path escapes its root: ${relative}`);
310	  return resolved;
311	}
312	
313	export function assertNoSymlinks(root) {
314	  const visit = (dir) => {
315	    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
316	      const item = path.join(dir, entry.name);
317	      if (entry.isSymbolicLink()) throw new Error(`task tree contains a symlink: ${path.relative(root, item)}`);
318	      if (entry.isDirectory()) visit(item);
319	    }
320	  };
321	  visit(root);
322	}
