198	      : agent.code === 0 && !agent.timedOut && !agent.outputExceeded;
199	    return {
200	      ...base,
201	      wallMs,
202	      exitCode: agent.code,
203	      timedOut: agent.timedOut,
204	      outputExceeded: agent.outputExceeded,
205	      turn: turn && { execution: turn.execution, outcome: turn.outcome, reason: turn.reason ?? null, steps: turn.steps ?? null, contextNotRetained: turn.contextNotRetained ?? 0 },
206	      claimedComplete,
207	      claimedVerified: turn?.outcome === "VERIFIED",
208	      hiddenPass: hidden.pass,
209	      regressionPass: regression ? regression.pass : null,
210	      falseVerified: turn?.outcome === "VERIFIED" && !hidden.pass,
211	      contaminated,
212	      tokens: agent.json?.tokenStats ?? null,
213	      model,
214	      logs: saveLogs(task, run, agent, hidden, regression),
215	    };
216	  } catch (err) {
217	    return { ...base, wallMs: 0, error: String(err?.message ?? err), hiddenPass: false, regressionPass: null, falseVerified: false, claimedComplete: false, claimedVerified: false };
218	  } finally {
219	    if (!args.keep) {
220	      fs.rmSync(ws, { recursive: true, force: true });
221	      fs.rmSync(home, { recursive: true, force: true });
222	    }
223	  }
224	}
225	
226	async function prepareWorkspace(task, ws) {
227	  if (task.fixture) {
228	    const fixture = confinedPath(task.dir, task.fixture);
229	    assertNoSymlinks(fixture);
230	    fs.cpSync(fixture, ws, { recursive: true, verbatimSymlinks: true });
231	    sh("git", ["init", "-q"], ws);
232	    sh("git", ["add", "-A"], ws);
233	    sh("git", ["-c", "user.name=eval", "-c", "user.email=eval@example.invalid", "commit", "-qm", "fixture"], ws);
234	  } else if (task.repo) {
235	    const cache = path.join(ROOT, "eval/.cache", createHash("sha256").update(task.repo.url).digest("hex").slice(0, 16));
236	    if (!fs.existsSync(cache)) sh("git", ["clone", "-q", "--no-checkout", task.repo.url, cache], ROOT);
237	    const object = `${task.repo.commit}^{commit}`;
238	    if (sh("git", ["-C", cache, "cat-file", "-e", object], ROOT, true) !== 0) sh("git", ["-C", cache, "fetch", "-q", "origin", task.repo.commit], ROOT);
239	    sh("git", ["clone", "-q", "--shared", cache, ws], ROOT);
240	    sh("git", ["-C", ws, "checkout", "-q", task.repo.commit], ROOT);
241	  } else throw new Error(`task ${task.id} has neither fixture nor repo`);
242	  for (const cmd of task.setup ?? []) {
243	    const result = await runIsolated(cmd, { cwd: ws, home: true, timeoutSec: task.setupTimeoutSec ?? 300 });
244	    if (result.status !== 0 || result.timedOut || result.overflow) throw new Error(`isolated setup failed for ${task.id}: ${result.timedOut ? "timeout" : result.overflow ? "output limit" : `exit ${result.status}`}`);
245	  }
246	}
247	
248	/**
249	 * The command line and environment for one agent run. Each agent gets a fresh HOME holding only its gateway settings
250	 * (no operator plugins, extensions or memory), the same endpoint and model, and the key through its environment.
251	 */
252	function effectiveBudget(task, config) {
253	  return { steps: task.steps ?? config.steps ?? 300, minutes: task.minutes ?? config.minutes ?? 120 };
254	}
255	
256	async function resolveAgentIdentity(config) {
257	  const agent = config.agent ?? "nexus";
258	  let command;
259	  let argsPrefix = [];
260	  if (agent === "nexus") {
261	    if (config.qualification === true) {
262	      if (typeof config.nexusExecutable !== "string" || !path.isAbsolute(config.nexusExecutable)) {
263	        return { record: null, problem: "qualification requires nexusExecutable to be the absolute path of the installed RC" };
264	      }
265	      if (typeof config.expectedAgentVersion !== "string" || !config.expectedAgentVersion.trim()) {
266	        return { record: null, problem: "qualification requires expectedAgentVersion to pin the installed RC" };
267	      }
268	      if (!/^[0-9a-f]{64}$/.test(config.nexusPackageSha256 ?? "")) {
269	        return { record: null, problem: "qualification requires nexusPackageSha256 from the installed RC release asset" };
270	      }
271	      command = path.resolve(config.nexusExecutable);
272	      try {
273	        if (fs.realpathSync(command) === fs.realpathSync(path.join(ROOT, "cli/dist/index.js"))) {
274	          return { record: null, problem: "qualification must use the installed RC, not the checkout cli/dist/index.js" };
275	        }
276	      } catch {}
277	    } else {
278	      command = process.execPath;
279	      argsPrefix = [path.join(ROOT, "cli/dist/index.js")];
280	    }
281	  } else if (["goose", "opencode", "aider"].includes(agent)) {
282	    command = resolvePathExecutable(agent, { ...process.env, ...(config.env ?? {}) }) ?? agent;
283	  } else {
284	    return { record: null, problem: `eval agent '${agent}' has no versioned adapter` };
285	  }
286	
287	  const required = config.qualification === true || config.expectedAgentVersion !== undefined;
288	  let candidatePath;
289	  try { candidatePath = fs.realpathSync(command); }
290	  catch (error) { return { record: null, problem: required ? `could not identify ${agent} executable (${error.message})` : null, command, argsPrefix }; }
291	  argsPrefix = argsPrefix.map((item) => path.isAbsolute(item) ? fs.realpathSync(item) : item);
292	  const probeWorkspace = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-eval-version-workspace-"));
293	  let probe;
294	  try {
295	    const runtimePaths = [candidatePath, ...argsPrefix.filter((item) => path.isAbsolute(item)).map((item) => fs.realpathSync(item))];
296	    const isCheckoutNexus = agent === "nexus" && argsPrefix[0] === path.join(ROOT, "cli/dist/index.js");
297	    if (isCheckoutNexus) {
298	      runtimePaths.push(path.join(ROOT, "cli/dist"));
299	      const modules = path.join(ROOT, "cli/node_modules");
300	      if (fs.existsSync(modules)) {
301	        for (const entry of fs.readdirSync(modules, { withFileTypes: true })) {
302	          if (entry.isDirectory() && entry.name !== ".bin") runtimePaths.push(path.join(modules, entry.name));
303	        }
304	      }
305	      const coreBinary = path.join(ROOT, "core/target/release/harness-core");
306	      if (fs.existsSync(coreBinary)) runtimePaths.push(coreBinary);
307	    }
308	    const allowedRoots = [...new Set([...(config.sandboxRuntimeRoots ?? []), ...(isCheckoutNexus ? [ROOT] : [])])];
309	    const spec = isolatedProcessArgv({
310	      cwd: probeWorkspace,
311	      command: candidatePath,
312	      argv: [...argsPrefix, "--version"],
313	      readOnlyPaths: [...new Set(runtimePaths)],
314	      allowedRoots,
315	      allowedFiles: [candidatePath, ...argsPrefix.filter((item) => path.isAbsolute(item))],
316	      timeoutMs: 5000,
317	    });
318	    const wrapped = config.runAs ? asUser(config.runAs, spec.cmd, spec.argv, {}) : spec;
319	    probe = await runIsolatedProcess(wrapped, { outputLimit: 4096 });
320	  } finally {
321	    fs.rmSync(probeWorkspace, { recursive: true, force: true });
322	  }
323	  const output = `${probe?.stdout ?? ""}${probe?.stderr ?? ""}`.trim();
324	  const version = output.split(/\r?\n/, 1)[0]?.trim().slice(0, 200) || null;
325	  if (probe?.error || probe?.status !== 0 || probe?.timedOut || probe?.overflow || !version) {
326	    const reason = probe?.error ?? (probe?.timedOut ? "timeout" : probe?.overflow ? "output limit exceeded" : `exit ${probe?.status ?? "unknown"}`);
327	    return { record: null, problem: required ? `could not identify ${agent} version (${reason})` : null, command, argsPrefix };
328	  }
329	
330	  const versionMatch = /\bv?(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)(?=\b)/.exec(version);
331	  const expected = typeof config.expectedAgentVersion === "string" ? config.expectedAgentVersion.replace(/^v/, "") : null;
332	  if (expected && versionMatch?.[1] !== expected) {
333	    const label = agent === "nexus" ? "installed Nexus" : agent;
334	    const kind = agent === "nexus" ? "expected RC" : "expected version";
335	    return { record: null, problem: `${label} version ${versionMatch?.[1] ?? version} does not match ${kind} ${expected}`, command, argsPrefix };
336	  }
337	
338	  let executablePath;
339	  let executableSha256;
340	  try {
341	    executablePath = agent === "nexus" && argsPrefix.length ? fs.realpathSync(argsPrefix[0]) : fs.realpathSync(command);
342	    executableSha256 = await sha256File(executablePath);
343	  } catch (err) {
344	    if (required) return { record: null, problem: `could not hash ${agent} executable (${err.message})`, command, argsPrefix };
345	  }
346	  return {
347	    record: {
348	      agent,
349	      version,
350	      ...(executablePath ? { executablePath } : {}),
351	      ...(executableSha256 ? { executableSha256 } : {}),
352	      ...(agent === "nexus" && config.qualification === true ? { packageSha256: config.nexusPackageSha256 } : {}),
353	    },
354	    command,
355	    argsPrefix,
356	  };
357	}
358	
359	function resolvePathExecutable(command, env) {
360	  for (const directory of (env.PATH ?? "").split(path.delimiter).filter(Boolean)) {
361	    const candidate = path.resolve(directory, command);
362	    try {
363	      if (fs.statSync(candidate).isFile()) return fs.realpathSync(candidate);
364	    } catch {}
365	  }
366	  return null;
367	}
368	
369	function sha256File(file) {
370	  return new Promise((resolve, reject) => {
371	    const hash = createHash("sha256");
372	    const stream = fs.createReadStream(file);
373	    stream.on("data", (chunk) => hash.update(chunk));
374	    stream.on("error", reject);
375	    stream.on("end", () => resolve(hash.digest("hex")));
376	  });
377	}
378	
379	function agentCommand(task, ws, home, budget, agentIdentity, localToken) {
380	  const sampling = config.sampling ?? { temperature: 0.2 };
381	  const limits = config.limits ?? { context: 65536, output: 8192 };
382	  const forbiddenEnv = Object.keys(config.env ?? {}).find((key) => /KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL/i.test(key));
383	  if (forbiddenEnv) throw new Error(`candidate configuration may not contain credential-like environment key ${forbiddenEnv}`);
384	  const ep = "http://127.0.0.1:40127/v1";
385	  const env = {
386	    PATH: config.env?.PATH ?? "/usr/bin:/bin", LANG: config.env?.LANG ?? "C.UTF-8", LC_ALL: config.env?.LC_ALL ?? "C.UTF-8",
387	    TERM: config.env?.TERM ?? "dumb", HOME: "/home/eval", PWD: "/workspace", CI: "1",
388	    LOCAL_LLM_API_KEY: localToken, OPENAI_API_KEY: localToken, GW_KEY: localToken,
389	    XDG_CONFIG_HOME: "/home/eval/.config", XDG_DATA_HOME: "/home/eval/.local/share", XDG_STATE_HOME: "/home/eval/.local/state",
390	  };
391	  const agent = config.agent ?? "nexus";
392	  if (agent === "nexus") {
393	    env.LOCAL_LLM_ENDPOINT = ep;
394	    const contextArgs = nexusContextLimitArgs(config, limits.context);
395	    return { cmd: agentIdentity.command, argv: [...agentIdentity.argsPrefix, "run", "--yes", "--json", "-w", "/workspace", "-e", ep, "-m", config.model, "-t", String(sampling.temperature), "-s", "30", "--max-total-steps", String(budget.steps), "--max-turn-minutes", String(budget.minutes), ...contextArgs, ...(config.args ?? []), task.objective], env };
396	  }
397	  if (agent === "aider") {
398	    return { cmd: agentIdentity.command, argv: ["--model", `openai/${config.model}`, "--openai-api-base", ep, "--yes-always", "--no-auto-commits", "--no-dirty-commits", "--no-gitignore", "--no-show-model-warnings", "--no-check-update", "--analytics-disable", "--no-pretty", "--no-fancy-input", ...(config.args ?? []), "--message", task.objective], env };
399	  }
400	  if (agent === "opencode") {
401	    const dir = path.join(home, ".config/opencode");
402	    fs.mkdirSync(dir, { recursive: true });
403	    const modelOptions = { temperature: sampling.temperature, ...(sampling.seed !== undefined ? { seed: sampling.seed } : {}) };
404	    fs.writeFileSync(path.join(dir, "opencode.json"), JSON.stringify({
405	      $schema: "https://opencode.ai/config.json",
406	      autoupdate: false,
407	      share: "disabled",
408	      permission: { edit: "allow", bash: "allow", webfetch: "deny" },
409	      agent: { "nexus-eval": { mode: "primary", steps: budget.steps } },
410	      provider: { gw: { npm: "@ai-sdk/openai-compatible", name: "gateway", options: { baseURL: ep, apiKey: "{env:GW_KEY}" }, models: { [config.model]: { name: config.model, limit: limits, options: modelOptions } } } },
411	      model: `gw/${config.model}`,
412	    }, null, 2));
413	    // Provider packages are cached across runs (not per run): the cache holds code, not state.
414	    env.XDG_CACHE_HOME = path.join(home, ".cache");
415	    return { cmd: agentIdentity.command, argv: ["run", "--agent", "nexus-eval", "--model", `gw/${config.model}`, ...(config.args ?? []), task.objective], env };
416	  }
417	  if (agent === "goose") {
418	    const u = new URL(ep);
419	    Object.assign(env, { GOOSE_PROVIDER: "openai", GOOSE_MODEL: config.model, OPENAI_HOST: u.origin, OPENAI_BASE_PATH: `${u.pathname.replace(/^\/|\/$/g, "")}/chat/completions`, GOOSE_MODE: "auto", GOOSE_DISABLE_KEYRING: "1", GOOSE_CONTEXT_LIMIT: String(limits.context), GOOSE_MAX_TOKENS: String(limits.output), GOOSE_MAX_TURNS: String(budget.steps), GOOSE_TEMPERATURE: String(sampling.temperature) });
420	    return { cmd: agentIdentity.command, argv: ["run", "--no-session", "--with-builtin", "developer", "--max-turns", String(budget.steps), ...(config.args ?? []), "-t", task.objective], env };
421	  }
422	  throw new Error(`agent ${agent} has no adapter`);
423	}
424	
425	function runAgent(task, ws, home, budget, agentIdentity, proxyDirectory, localToken) {
426	  const { cmd, argv, env } = agentCommand(task, ws, home, budget, agentIdentity, localToken);
427	  if (config.qualification === true && !config.runAs) throw new Error("qualification candidate execution requires the dedicated evaluator account");
428	  if (config.runAs) grantRunAsAccess(config.runAs, [ws, home, proxyDirectory]);
429	  const runtimePaths = [fs.realpathSync(cmd), ...agentIdentity.argsPrefix.filter((item) => path.isAbsolute(item)), ...(config.sandboxRuntimePaths ?? [])];
430	  if ((config.agent ?? "nexus") === "nexus" && agentIdentity.argsPrefix[0] === path.join(ROOT, "cli/dist/index.js")) {
431	    runtimePaths.push(path.join(ROOT, "cli/dist"));
432	    const modules = path.join(ROOT, "cli/node_modules");
433	    for (const entry of fs.readdirSync(modules, { withFileTypes: true })) {
434	      if (entry.isDirectory() && entry.name !== ".bin") runtimePaths.push(path.join(modules, entry.name));
435	    }
436	    const coreBinary = path.join(ROOT, "core/target/release/harness-core");
437	    if (fs.existsSync(coreBinary)) runtimePaths.push(coreBinary);
438	  }
439	  const sandboxRuntimePaths = [...new Set(runtimePaths)];
440	  const allowedRuntimeRoots = [...new Set([...(config.sandboxRuntimeRoots ?? []), ...((config.agent ?? "nexus") === "nexus" && agentIdentity.argsPrefix[0] === path.join(ROOT, "cli/dist/index.js") ? [ROOT] : [])])];
441	  const sandbox = agentSandboxArgv({ cwd: ws, home, proxyDirectory, readOnlyPaths: sandboxRuntimePaths, allowedRuntimeRoots, runtimeExecutablePaths: [cmd, ...agentIdentity.argsPrefix], supervisorPath: path.join(ROOT, "eval/agent_sandbox.mjs") });
442	  const wrapped = config.runAs ? asUser(config.runAs, sandbox.cmd, sandbox.argv, {}) : sandbox;
443	  return new Promise((resolve) => {
444	    const child = spawn(wrapped.cmd, wrapped.argv, { cwd: "/", env: {}, stdio: ["pipe", "pipe", "pipe"], detached: true });
445	    child.stdin.end(JSON.stringify({ command: cmd, argv, env }));
446	    let stdout = "";
447	    let stderr = "";
448	    let timedOut = false;
449	    let outputExceeded = false;
450	    let outputBytes = 0;
451	    const collect = (target, chunk) => {
452	      outputBytes += chunk.length;
453	      if (outputBytes > 2_000_000) {
454	        outputExceeded = true;
455	        killGroup("SIGKILL");
456	        return;
457	      }
458	      if (target === "stdout") stdout += chunk;
459	      else stderr += chunk;
460	    };
461	    child.stdout.removeAllListeners("data");
462	    child.stderr.removeAllListeners("data");
463	    child.stdout.on("data", (c) => collect("stdout", c));
464	    child.stderr.on("data", (c) => collect("stderr", c));
465	    // The whole process group: agents start helpers (servers, shells) that must not outlive the run.
466	    const killGroup = (sig) => {
467	      try {
468	        process.kill(-child.pid, sig);
469	      } catch {}
470	    };
471	    const timer = setTimeout(() => {
472	      timedOut = true;
473	      killGroup("SIGTERM");
474	      setTimeout(() => killGroup("SIGKILL"), 10_000).unref();
475	    }, (budget.minutes + 5) * 60_000);
476	    child.on("error", (err) => (stderr += `spawn error: ${err.message}\n`));
477	    child.on("close", (code) => {
478	      clearTimeout(timer);
479	      killGroup("SIGKILL");
480	      resolve({ code, timedOut, outputExceeded, stdout, stderr, json: lastJson(stdout) });
481	    });
482	  });
483	}
484	
485	function runCheck(task, ws, check, hidden) {
486	  if (hidden && check.protocol === "blackbox-v1") {
487	    return runBlackBoxOracle(task, ws, check).then((result) => ({
488	      ...result,
489	      status: result.pass ? 0 : 1,
490	      output: JSON.stringify({
491	        cases: result.cases,
492	        failedCases: result.failedCases,
493	        timeoutCases: result.timeoutCases,
494	        outputLimitCases: result.outputLimitCases,
495	        executionFailureCases: result.executionFailureCases,
496	        invalidOutputCases: result.invalidOutputCases,
497	        mismatchCases: result.mismatchCases,
498	        outcome: result.outcome,
499	      }),
500	    }));
501	  }
502	  if (hidden && check.dir) {
503	    const source = confinedPath(task.dir, check.dir);
504	    assertNoSymlinks(source);
505	    const relativeTarget = check.into ?? check.dir;
506	    const destination = confinedPath(ws, relativeTarget, { allowMissingLeaf: true });
507	    fs.cpSync(source, destination, { recursive: true, verbatimSymlinks: true });
508	  }
509	  return runIsolated(check.command, { cwd: ws, home: true, timeoutSec: check.timeoutSec ?? 300, outputLimit: 1_000_000 })
510	    .then((r) => ({ pass: r.status === 0 && !r.timedOut && !r.overflow, status: r.status, timedOut: r.timedOut, overflow: r.overflow, output: `${r.stdout}${r.stderr}`.slice(-20_000) }));
511	}
512	
513	function saveLogs(task, run, agent, hidden, regression) {
514	  const dir = path.join(args.out, "logs", `${task.id}-${run}`);
515	  fs.mkdirSync(dir, { recursive: true });
516	  fs.writeFileSync(path.join(dir, "agent.stdout.json"), agent.stdout);
517	  fs.writeFileSync(path.join(dir, "agent.stderr.log"), agent.stderr.slice(-200_000));
518	  fs.writeFileSync(path.join(dir, "hidden.log"), hidden.output);
519	  if (regression) fs.writeFileSync(path.join(dir, "regression.log"), regression.output);
520	  return path.relative(args.out, dir);
521	}
522	
523	function treeDigest(dir) {
524	  return taskTreeDigest(dir);
525	}
526	
527	function lastJson(text) {
528	  const start = text.indexOf("{");
529	  for (let i = start; i >= 0 && i < text.length; i = text.indexOf("{", i + 1)) {
530	    try {
531	      return JSON.parse(text.slice(i));
532	    } catch {}
533	  }
534	  return null;
535	}
536	
537	function harnessIdentity() {
538	  const git = (...a) => spawnSync("git", a, { cwd: ROOT, encoding: "utf8" }).stdout.trim();
539	  const commit = git("rev-parse", "HEAD");
540	  const dirty = Boolean(git("status", "--porcelain", "--untracked-files=all", "--", ".", ":(exclude)cli/dist"));
541	  const sourceFiles = ["eval/run.mjs", "eval/validate.mjs", "eval/isolate.mjs", "eval/agent_sandbox.mjs", "eval/model_proxy.mjs", "eval/score.mjs", "eval/infra.mjs"];
542	  const sourceDigests = sourceFiles.map((file) => ({ file, sha256: createHash("sha256").update(fs.readFileSync(path.join(ROOT, file))).digest("hex") }));
543	  const sourceSha256 = createHash("sha256").update(JSON.stringify(sourceDigests)).digest("hex");
544	  return { commit, dirty, sourceDigests, sourceSha256, string: `${commit.slice(0, 12)}${dirty ? "-dirty" : ""}` };
545	}
546	
547	/** `{ file, var }`: the key is read from a KEY=value file (e.g. ~/.config/nexus/config.env); never logged. */
548	function readApiKey(spec) {
549	  if (!spec) return null;
550	  const file = expandHome(spec.file);
551	  const line = fs.readFileSync(file, "utf8").split("\n").find((l) => l.startsWith(`${spec.var}=`));
552	  if (!line) throw new Error(`${spec.var} not found in ${spec.file}`);
553	  return line.slice(spec.var.length + 1).trim();
554	}
555	
556	/** System CAs plus the gateway's CA, for agents that read SSL_CERT_FILE / REQUESTS_CA_BUNDLE (Python, Rust). */
557	function writeCaBundle(caFile) {
558	  const system = ["/etc/ssl/certs/ca-certificates.crt", "/etc/pki/tls/certs/ca-bundle.crt"].find((f) => fs.existsSync(f));
559	  const bundle = path.join(args.out, "ca-bundle.pem");
560	  fs.writeFileSync(bundle, (system ? fs.readFileSync(system, "utf8") : "") + "\n" + fs.readFileSync(caFile, "utf8"));
561	  return bundle;
562	}
563	
564	function redactConfig(c) {
565	  const env = Object.fromEntries(Object.entries(c.env ?? {}).map(([k, v]) => [k, /KEY|TOKEN|SECRET|PASSWORD/i.test(k) ? "***" : v]));
566	  return { ...c, env };
567	}
568	
569	function expandHome(f) {
570	  return f.replace(/^~(?=\/)/, os.homedir());
571	}
572	
573	function sh(command, argv, cwd, allowFailure = false) {
574	  const r = spawnSync(command, argv, {
575	    cwd,
576	    encoding: "utf8",
577	    timeout: 120_000,
578	    env: { PATH: "/usr/bin:/bin", HOME: os.tmpdir(), GIT_CONFIG_NOSYSTEM: "1", GIT_CONFIG_GLOBAL: "/dev/null", GIT_TERMINAL_PROMPT: "0", GIT_ALLOW_PROTOCOL: "https" },
579	  });
580	  if (r.status !== 0 && !allowFailure) throw new Error(`${path.basename(command)} failed (${r.status ?? "signal"}): ${(r.stderr || r.stdout || "").slice(-2000)}`);
581	  return r.status;
582	}
583	
584	function parseArgs(list) {
585	  const out = {};
586	  for (let i = 0; i < list.length; i++) {
587	    const key = list[i].replace(/^--/, "");
588	    const next = list[i + 1];
589	    if (next === undefined || next.startsWith("--")) out[key] = true;
590	    else {
591	      out[key] = next;
592	      i++;
593	    }
594	  }
595	  return out;
596	}
