edit('eval/validate.mjs', [('''export function asUser(user, cmd, argv, env) {
  const assignments = Object.entries(env).filter(([, v]) => v !== undefined).map(([k, v]) => `${k}=${v}`);
  return { cmd: "sudo", argv: ["-n", "-u", user, "--", "env", "-i", ...assignments, cmd, ...argv] };
}''','''/**
 * Run `cmd` as the evaluator account. sudo resets the environment (env_reset) and every caller passes Bubblewrap,
 * which clears it again, so the sudoers rule can name only /usr/bin/bwrap (eval/host/README.md) instead of `env`,
