        return ("text", "宽字符测试 全角ＡＢＣ emoji 👩‍👩‍👧 🎉 combining é (é) RTL שלום tab\there " + "x" * 150, 0)
    if scenario == "http500":
        return ("http", 500, 0)
    return ("text", "Hello from mock.", 0)


